#!/usr/bin/env node
/**
 * Bundle `supabase/migrations/*.sql` into a TS module the runtime can import.
 *
 * WHY NOT READ THE FILES AT RUNTIME. On Vercel only what the build traces ends
 * up in the deployment; a `fs.readFileSync` of a directory that nothing imports
 * is exactly the kind of thing that works locally and is missing in
 * production. Inlining the SQL into a module makes the migrations part of the
 * bundle by construction, so "the deployment carries its own migrations" is a
 * fact rather than a hope.
 *
 * The generated file is COMMITTED. That keeps the build free of a codegen step
 * (one less thing to fail in CI), and a test asserts the committed output still
 * matches the .sql files so the two cannot silently diverge.
 *
 *   node scripts/bundle-migrations.mjs [--check]
 *
 * --check exits non-zero if the committed bundle is stale, without writing.
 */

import { readdirSync, readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const agentsRoot = resolve(here, "..");
// The store repo keeps migrations beside the console, not inside it.
const candidates = [
  resolve(agentsRoot, "..", "supabase", "migrations"),
  resolve(agentsRoot, "supabase", "migrations"),
];
const srcDir = candidates.find((d) => existsSync(d));
const outFile = join(agentsRoot, "lib", "migrations", "bundled.ts");

const header = `/**
 * GENERATED by scripts/bundle-migrations.mjs — do not edit.
 *
 * The SQL below is inlined so the deployment carries its own migrations (see
 * the script's header for why runtime file reads are not reliable on Vercel).
 * Regenerate with: node scripts/bundle-migrations.mjs
 */

export interface BundledMigration {
  name: string;
  sql: string;
}

export const MIGRATIONS: BundledMigration[] = [
`;

const files = srcDir
  ? readdirSync(srcDir)
      .filter((f) => f.endsWith(".sql"))
      .sort()
  : [];

const body = files
  .map((f) => {
    const sql = readFileSync(join(srcDir, f), "utf8");
    // Backtick-safe: SQL should never contain them, but never assume.
    const escaped = sql.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
    return `  {\n    name: ${JSON.stringify(f)},\n    sql: \`${escaped}\`,\n  },`;
  })
  .join("\n");

const out = `${header}${body}\n];\n`;

if (process.argv.includes("--check")) {
  const current = existsSync(outFile) ? readFileSync(outFile, "utf8") : "";
  if (current !== out) {
    console.error(
      `[bundle-migrations] ${outFile} is STALE — run: node scripts/bundle-migrations.mjs`,
    );
    process.exit(1);
  }
  console.log(`[bundle-migrations] bundle is current (${files.length} migration(s))`);
  process.exit(0);
}

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, out);
console.log(
  srcDir
    ? `[bundle-migrations] wrote ${files.length} migration(s) from ${srcDir}`
    : "[bundle-migrations] no migrations directory found — wrote an empty bundle",
);
